/* Files stay in this browser. Only notice text goes to the AI service. */
(()=>{
'use strict';
const MAX_FILE=5*1024*1024,MAX_TOTAL=20*1024*1024,MAX_BACKUP=50*1024*1024;
let database;
function db(){if(!database)database=new Promise((resolve,reject)=>{const request=indexedDB.open('campus-inbox-files',1);request.onupgradeneeded=()=>request.result.createObjectStore('files',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(new Error('附件存储不可用，请检查浏览器存储设置。'));});return database;}
async function transaction(mode,operation){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files',mode);let result;try{result=operation(tx.objectStore('files'));}catch(e){tx.abort();reject(e);return;}tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(new Error('附件未能保存，浏览器存储空间可能不足。'));tx.onabort=()=>reject(new Error('附件保存已取消。'));});}
async function get(id){const database=await db();return new Promise((resolve,reject)=>{const r=database.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(new Error('无法读取附件。'));});}
function validate(files){if(files.length>10)throw new Error('每条通知最多10个附件。');if(files.some(f=>f.size>MAX_FILE))throw new Error('单个附件不能超过5 MB。');if(files.reduce((s,f)=>s+f.size,0)>MAX_TOTAL)throw new Error('一条通知的附件总大小不能超过20 MB。');}
async function putFiles(files){validate(files);if(!files.length)return [];const records=files.map(f=>({id:crypto.randomUUID(),name:f.name.slice(0,250)||'附件',type:f.type.slice(0,100),size:f.size,blob:f}));await transaction('readwrite',store=>records.forEach(r=>store.put(r)));return records.map(r=>r.id);}
async function remove(ids){if(!ids.length)return;await transaction('readwrite',store=>ids.forEach(id=>store.delete(id)));}
async function cleanup(ids,notices){const used=new Set(notices.flatMap(n=>n.attachments));await remove([...new Set(ids)].filter(id=>!used.has(id)));}
function base64(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('无法导出附件。'));reader.readAsDataURL(blob);});}
async function exportFiles(notices){const ids=[...new Set(notices.flatMap(n=>n.attachments))];let size=0;const files=[];for(const id of ids){const file=await get(id);if(!file)throw new Error('有附件未保存在此浏览器，无法生成完整备份。');size+=file.size;if(size>MAX_BACKUP)throw new Error('附件总大小超过50 MB，请减少附件后导出。');files.push({id,name:file.name,type:file.type,size:file.size,data:await base64(file.blob)});}return files;}
async function restore(body,notices){const required=new Set(notices.flatMap(n=>n.attachments));if(!required.size)return {notices,ids:[]};if(!Array.isArray(body.attachments)||body.attachments.length>2000)throw new Error('备份缺少附件或附件过多。');const records=[],mapping=new Map();let total=0;for(const f of body.attachments){if(!f||!required.has(f.id)||mapping.has(f.id)||typeof f.name!=='string'||!f.name||f.name.length>250||typeof f.type!=='string'||f.type.length>100||!Number.isInteger(f.size)||f.size<0||f.size>MAX_FILE||typeof f.data!=='string'||f.data.length>Math.ceil(MAX_FILE/3)*4||!/^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(f.data))throw new Error('附件备份格式不正确。');const bytes=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0));if(bytes.length!==f.size)throw new Error('附件大小与备份记录不一致。');total+=f.size;if(total>MAX_BACKUP)throw new Error('附件备份超过50 MB。');const id=crypto.randomUUID();mapping.set(f.id,id);records.push({id,name:f.name,type:f.type,size:f.size,blob:new Blob([bytes],{type:f.type})});}if(mapping.size!==required.size)throw new Error('备份中有附件缺失。');for(const n of notices){validate(n.attachments.map(id=>records.find(r=>r.id===mapping.get(id))));}await transaction('readwrite',store=>records.forEach(r=>store.put(r)));return {notices:notices.map(n=>({...n,attachments:n.attachments.map(id=>mapping.get(id))})),ids:records.map(r=>r.id)};}
globalThis.CampusAttachments={MAX_FILE,MAX_TOTAL,MAX_BACKUP,validate,get,putFiles,remove,cleanup,exportFiles,restore};
})();
